      "11歳男児。給食後の体育の授業中に、顔面、頸部、躯幹にじん麻疹が突然出現し、意識消失により病院へ搬送された。その後、入院加療により改善し、退院時にアドレナリンの自己注射薬の処方を受けた。\n\nこの患者は、アドレナリンの自己注射薬を初めて携帯することになった。注射薬交付にあたって指導すべき内容に関して適切でないのはどれか。2つ選べ。",

